// pages/Feed.jsx
import React, { useEffect, useState } from 'react';
import ReviewCard from '../components/ReviewCard';
import Composer from '../components/Composer';
import { fetchReviews, createReview } from '../api/reviewApi';
import { useAuth } from '../hooks/useAuth';

// Feed: updated UI — hero banner, prominent roulette CTA, composer and 3-column grid

  const sampleReviews = [
  {
    _id: 'r001', author: { username: '수아' }, title: '피부가 환해지는 비타민C 세럼', text: '2주 사용했는데 피부톤이 확실히 밝아졌어요! 흡수도 빠르고 끈적임 없이 촉촉해요. 아침에 바르면 화장도 더 잘 먹는 느낌이에요 💛', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 24, likes: 456, comments: 38, tags: ['세럼', '미백', '비타민C'], rating: 4.8
  },
  { _id: 'r002', author: { username: '민지' }, title: '촉촉한 수분크림 추천합니다', text: '건성 피부인데 이 크림 바르고 아침까지 촉촉해요. 향도 은은하고 좋아요. 가격 대비 용량도 넉넉해서 만족스러워요 ✨', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 48, likes: 289, comments: 22, tags: ['수분크림', '보습', '건성피부'], rating: 4.5 },
  { _id: 'r003', author: { username: '윤서' }, title: '커버력 좋은 쿠션 파운데이션', text: '얇게 발리는데 커버력은 확실해요. 무너짐도 적고 자연스러운 광채가 예뻐요. 여름에도 잘 버틸 것 같아요!', images: ['/images/파운데이션리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 72, likes: 523, comments: 45, tags: ['쿠션', '베이스', '커버력'], rating: 4.7 },
  { _id: 'r004', author: { username: '지우' }, title: '블랙헤드 제거 클렌징폼', text: '매일 사용하면서 모공이 점점 깨끗해지는 게 느껴져요. 거품도 풍성하고 세안 후 땅기지 않아서 좋아요 🧼', images: ['/images/클렌징폼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 5, likes: 367, comments: 29, tags: ['클렌징', '모공케어', '블랙헤드'], rating: 4.6 },
  { _id: 'r005', author: { username: '하은' }, title: '발색 예쁜 틴트 립스틱', text: '색상이 정말 예뻐요! 발색도 좋고 지속력도 만족스러워요. 입술도 안 건조해지고 데일리로 딱이에요 💄', images: ['/images/립스틱리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 120, likes: 612, comments: 51, tags: ['립스틱', '틴트', '립메이크업'], rating: 4.9 },
  { _id: 'r006', author: { username: '서연' }, title: '진정 효과 좋은 마스크팩', text: '피부 진정에 최고예요. 민감해진 피부에 붙이면 바로 차분해져요. 매일 사용해도 부담 없는 가격이 좋아요 🌿', images: ['/images/마스크팩리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 200, likes: 198, comments: 16, tags: ['마스크팩', '진정', '민감피부'], rating: 4.4 },
];

function Feed() {
  const [reviews, setReviews] = useState([]);

  const { user, updateUserPoints } = useAuth();

  const saveAndPrepend = (item) => {
    setReviews(prev => [item, ...prev]);
  };

  const handleComposerSubmit = async ({ author, text, files, tags }) => {
    const payload = {
      author: { username: author || '익명' },
      title: '',
      text,
      images: (files || []).map(f => f.dataUrl),
      tags: tags || [],
    };
    try {
      const res = await createReview(payload);
      const created = res.data;
      saveAndPrepend(created);
    } catch (err) {
      // fallback: prepend local mock for demo
      console.warn('create review failed, using local mock', err);
      saveAndPrepend({ _id: `local-${Date.now()}`, author: { username: author || '익명' }, text, images: (files||[]).map(f=>f.dataUrl), likes: 0, comments: 0, createdAt: Date.now(), tags });
    }
  };

  useEffect(() => {
    // 화장품 리뷰 샘플 데이터를 우선 표시
    setReviews(sampleReviews);
    
    // API 데이터는 참고용으로만 로드 (주석 처리)
    /*
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 20 });
        setReviews(res.data && res.data.length ? res.data : sampleReviews);
      } catch (err) {
        console.warn('fetch reviews failed, loading sample data', err);
        setReviews(sampleReviews);
      }
    };
    load();
    */
  }, []);

  return (
    <div className="container page-enter" style={{ paddingTop: 18 }}>
      <header style={{ marginBottom: 18 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <div style={{ fontSize: 20, fontWeight: 800 }}>ReviewCommunity</div>
            <div style={{ color: '#666' }}>브랜드 매거진 + SNS형 리뷰 피드</div>
          </div>
          <div>
            <button className="btn" style={{ marginRight: 12, padding: '8px 12px', borderRadius: 8, border: '1px solid #e6eefb', background: '#fff' }}>쿠폰센터</button>
            <button className="btn btn-primary pointer bounce" style={{ padding: '10px 14px', borderRadius: 999 }}>🎡 룰렛 참여하기</button>
          </div>
        </div>
      </header>

      {/* Hero banner - 매거진 스타일 */}
      <section style={{ 
        background: 'linear-gradient(135deg, #fff5f7 0%, #ffeef4 50%, #fff 100%)', 
        borderRadius: 24, 
        padding: 0,
        marginBottom: 24,
        overflow: 'hidden',
        boxShadow: '0 20px 60px rgba(255,77,136,0.08)',
        border: '1px solid rgba(255,77,136,0.1)'
      }}>
        <div style={{ display: 'flex', alignItems: 'stretch' }}>
          {/* 텍스트 영역 */}
          <div style={{ flex: 1, padding: '40px 36px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <span style={{ 
              background: 'linear-gradient(135deg, #ff4d88, #ff8a5c)', 
              color: '#fff', 
              padding: '6px 14px', 
              borderRadius: 20, 
              fontSize: 11, 
              fontWeight: 700,
              width: 'fit-content',
              marginBottom: 16
            }}>✨ EDITOR'S PICK</span>
            <h2 style={{ margin: '0 0 12px', fontSize: 28, lineHeight: 1.3, fontWeight: 800 }}>
              오늘의 주목할만한<br/>
              <span style={{ background: 'linear-gradient(135deg, #ff4d88, #a855f7)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>뷰티 리뷰</span>
            </h2>
            <p style={{ color: '#666', fontSize: 15, lineHeight: 1.6, marginBottom: 20 }}>
              전문 크리에이터들의 생생한 사용후기와<br/>
              최신 브랜드 프로모션을 확인해보세요.
            </p>
            <div style={{ display: 'flex', gap: 12 }}>
              <button className="btn btn-primary" style={{ padding: '12px 24px', borderRadius: 12, fontWeight: 600 }}>지금 참여하기</button>
              <button className="btn" style={{ padding: '12px 24px', borderRadius: 12, border: '1px solid #e6eefb', background: '#fff' }}>트렌드 보기</button>
            </div>
            
            {/* 인기 태그 */}
            <div style={{ marginTop: 20, display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {['#비타민C세럼', '#수분크림', '#쿠션추천', '#데일리립'].map(tag => (
                <span key={tag} style={{ background: 'rgba(255,77,136,0.08)', color: '#ff4d88', padding: '6px 12px', borderRadius: 16, fontSize: 12, fontWeight: 500 }}>{tag}</span>
              ))}
            </div>
          </div>
          
          {/* 이미지 그리드 영역 */}
          <div style={{ width: 480, position: 'relative', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 0 }}>
            {/* 메인 이미지 */}
            <div style={{ gridColumn: 'span 2', height: 200, position: 'relative', overflow: 'hidden' }}>
              <img src="/images/립스틱리뷰.jpg" alt="Featured" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              <div style={{ position: 'absolute', bottom: 12, left: 12, background: 'rgba(0,0,0,0.6)', color: '#fff', padding: '6px 12px', borderRadius: 8, fontSize: 12, backdropFilter: 'blur(8px)' }}>
                💄 HERA 센시 립글로스 리뷰
              </div>
            </div>
            {/* 서브 이미지들 */}
            <div style={{ height: 120, overflow: 'hidden', position: 'relative' }}>
              <img src="/images/비타민세럼리뷰.jpg" alt="Skin" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              <div style={{ position: 'absolute', bottom: 8, left: 8, background: 'rgba(255,255,255,0.9)', padding: '4px 8px', borderRadius: 6, fontSize: 10, fontWeight: 600 }}>✨ 피부 광채</div>
            </div>
            <div style={{ height: 120, overflow: 'hidden', position: 'relative' }}>
              <img src="/images/마스크팩리뷰.jpg" alt="Mask" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              <div style={{ position: 'absolute', bottom: 8, left: 8, background: 'rgba(255,255,255,0.9)', padding: '4px 8px', borderRadius: 6, fontSize: 10, fontWeight: 600 }}>🌿 진정 케어</div>
            </div>
          </div>
        </div>
      </section>

      {/* Composer - 크리에이터 콘텐츠 작성 */}
      <div style={{ marginBottom: 24 }}>
        {/* 크리에이터 가이드 배너 */}
        <div style={{ 
          background: 'linear-gradient(135deg, #f0f9ff 0%, #fff 100%)', 
          borderRadius: 16, 
          padding: '16px 20px',
          marginBottom: 16,
          border: '1px solid rgba(59,130,246,0.1)',
          display: 'flex',
          alignItems: 'center',
          gap: 16
        }}>
          <div style={{ 
            width: 48, height: 48, 
            background: 'linear-gradient(135deg, #3b82f6, #8b5cf6)', 
            borderRadius: 12,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 24
          }}>📷</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 700, marginBottom: 2 }}>고품질 콘텐츠로 더 많은 관심을 받아보세요!</div>
            <div style={{ color: '#666', fontSize: 13 }}>조명이 좋은 제품 클로즈업, 발색샷, 비포/애프터 사진이 더 높은 참여율을 기록해요 ✨</div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>📸 제품 접사</span>
            <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>💄 발색샷</span>
            <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>✨ B&A</span>
          </div>
        </div>
        <Composer onSubmit={handleComposerSubmit} initialAuthor={user?.username || ''} />
      </div>

      {/* 카테고리 필터 탭 */}
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 8 }}>
          {[
            { id: 'all', name: '전체', icon: '✨' },
            { id: 'skincare', name: '스킨케어', icon: '💧' },
            { id: 'makeup', name: '메이크업', icon: '💄' },
            { id: 'bodycare', name: '바디케어', icon: '🧴' },
            { id: 'fashion', name: '패션', icon: '👗' },
            { id: 'lifestyle', name: '라이프스타일', icon: '🏠' },
          ].map((cat, idx) => (
            <button 
              key={cat.id}
              style={{ 
                padding: '10px 18px', 
                borderRadius: 20, 
                border: idx === 0 ? '2px solid #ff4d88' : '1px solid #e6eefb',
                background: idx === 0 ? 'linear-gradient(135deg, #fff0f5, #fff)' : '#fff',
                color: idx === 0 ? '#ff4d88' : '#666',
                fontWeight: idx === 0 ? 600 : 400,
                fontSize: 13,
                whiteSpace: 'nowrap',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                transition: 'all 0.2s ease'
              }}
            >
              <span>{cat.icon}</span> {cat.name}
            </button>
          ))}
        </div>
      </div>

      {/* Reviews grid - 다양한 카테고리 */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ margin: 0, fontSize: 18 }}>🔥 최신 리뷰</h3>
          <span style={{ color: '#888', fontSize: 13 }}>{reviews.length}개의 리뷰</span>
        </div>
        <div className="reviews-grid">
          {reviews.map(r => (
            <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} comments={r.comments} tags={r.tags} rating={r.rating} />
          ))}
        </div>
      </div>
    </div>
  );
}

export default Feed;
